#!/bin/bash
# Téléversement des GLB vers le stockage staging Shopify (POST signé Google).
set -e
cd "$(dirname "$0")/models"

up() { # $1 fichier, $2 key, $3 policy, $4 signature
  curl -s -o /dev/null -w "%{http_code} $1\n" \
    -F "GoogleAccessId=threed-model-service-prod@threed-model-service.iam.gserviceaccount.com" \
    -F "key=$2" -F "policy=$3" -F "signature=$4" \
    -F "file=@$1;type=model/gltf-binary" \
    "https://storage.googleapis.com/threed-models-production"
}

up "lustre-industriel-noir-6-lampes-salon-modele-neravio.glb" "models/0cd8fd4a642d278a/lustre-industriel-noir-6-lampes-salon-modele-neravio.glb" "" ""
